def main():
    n = int(input())
    p = list(map(lambda x: int(x) - 1, input().split()))
    s = list(input())

    def count_valid_configurations(s):
        sp = [True for _ in range(n)]
        valid = True
        for i in p:
            if s[i] == 'R':
                if sp[i]:
                    sp[i] = False
                elif sp[(i + 1) % n]:
                    sp[(i + 1) % n] = False
                else:
                    valid = False
                    break
            elif s[i] == 'L':
                if sp[(i + 1) % n]:
                    sp[(i + 1) % n] = False
                elif sp[i]:
                    sp[i] = False
                else:
                    valid = False
                    break
            elif s[i] == '?':
                if sp[i] and sp[(i + 1) % n]:
                    sp[i] = False
                elif sp[i]:
                    sp[i] = False
                elif sp[(i + 1) % n]:
                    sp[(i + 1) % n] = False
                else:
                    valid = False
                    break
        return valid

    def count_configurations(s, index):
        if index == n:
            return 1 if count_valid_configurations(s) else 0

        if s[index] == '?':
            s[index] = 'R'
            count_r = count_configurations(s, index + 1)
            s[index] = 'L'
            count_l = count_configurations(s, index + 1)
            s[index] = '?'
            return (count_r + count_l) % MOD
        else:
            return count_configurations(s, index + 1)

    result = count_configurations(s, 0)
